// news-image-20261121: a one-image front page for Saturday 21 November 2026.
//
// The entry is a program that writes one image to /output/entry.png. The
// image itself lives in this repository as entry.png (generated by the
// agent with an image model from the day's verified reporting), so this
// program only has to copy it into place. No network, no randomness, no
// clock: two runs write the same bytes every time. After copying, the
// program checks the output against the source (same size, PNG or JPEG
// magic bytes, and identical SHA-256 hash) and fails loudly instead of
// leaving a bad file behind.
//
// Run it outside the grader with:
//   mkdir -p out && MAKEFUN_OUTPUT_DIR=out node main.ts

import { createHash } from 'node:crypto';
import { copyFileSync, mkdirSync, readFileSync, statSync } from 'node:fs';
import { join } from 'node:path';

const outDir = process.env.MAKEFUN_OUTPUT_DIR?.trim() || '/output';
mkdirSync(outDir, { recursive: true });

const source = new URL('./entry.png', import.meta.url);
const dest = join(outDir, 'entry.png');
copyFileSync(source, dest);

// Verify the copy: the output must exist, be byte-for-byte the same size
// as the source, and start with valid PNG or JPEG magic bytes. A silent
// truncated or wrong-format copy would otherwise pass as a good entry.
const sourceBytes = statSync(source).size;
const destStat = statSync(dest);
if (destStat.size !== sourceBytes) {
  throw new Error(
    `entry.png copy failed: output is ${destStat.size} bytes, expected ${sourceBytes} bytes`,
  );
}
const magic = readFileSync(dest).subarray(0, 4);
const isPng =
  magic[0] === 0x89 && magic[1] === 0x50 && magic[2] === 0x4e && magic[3] === 0x47;
const isJpeg = magic[0] === 0xff && magic[1] === 0xd8 && magic[2] === 0xff;
if (!isPng && !isJpeg) {
  throw new Error(
    'entry.png copy failed: output does not start with valid PNG or JPEG magic bytes',
  );
}

// Byte-for-byte check: size and magic bytes alone cannot catch a copy
// that is the right length and format but has different content, so hash
// both files with SHA-256 and compare. Any mismatch fails the run.
const sourceHash = createHash('sha256').update(readFileSync(source)).digest('hex');
const destHash = createHash('sha256').update(readFileSync(dest)).digest('hex');
if (sourceHash !== destHash) {
  throw new Error(
    `entry.png copy failed: output SHA-256 ${destHash} does not match source SHA-256 ${sourceHash}`,
  );
}
